// ---- helpers ----
// QA #16 — ISO 4217 style: currency code + space + amount (symbol omitted).
// Applies to USD / CNY / NGN alike, on web console and H5.
function money(amount, currency) {
  const code = currency || 'USD';
  const num = new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount);
  return { code, num, text: `${code} ${num}`, full: `${code} ${num}` };
}
function tenantName(db, id) { const t = db.tenants.find(x => x.id === id); return t ? t.name : id; }
function tenantCode(db, id) { const t = db.tenants.find(x => x.id === id); return t ? t.code : id; }
function accountById(db, id) { return db.accounts.find(x => x.id === id); }
function productName(db, pid) { const p = db.products.find(x => x.id === pid); return p ? p.name : pid; }

// ---- R05 barcode helpers -------------------------------------------------
// Full barcode = tenant barcodePrefix + '-' + merchant-editable body.
// An empty string means "not encoded yet" (AC-05-07) and must stay empty —
// never fall back to the model code silently.
function splitBarcode(barcode) {
  const s = String(barcode || '');
  if (!s) return { prefix: '', body: '' };
  const i = s.indexOf('-');
  if (i < 0) return { prefix: '', body: s };
  return { prefix: s.slice(0, i), body: s.slice(i + 1) };
}
function isOwnBarcode(barcode, tenant) {
  const mine = ((tenant || {}).barcodePrefix || '').toUpperCase();
  return !!mine && splitBarcode(barcode).prefix.toUpperCase() === mine;
}
// R05 — 2–4 uppercase letters from the tenant name, serial-suffixed on collision.
// Uniqueness is checked against ALL tenants (Suspended ones included) so a
// retired prefix can never be recycled onto historical barcodes.
function makeBarcodePrefix(name, tenants) {
  const base = String(name || 'TT').replace(/[^A-Za-z]/g, '').toUpperCase().slice(0, 3) || 'TT';
  let p = base.length >= 2 ? base : base + 'X';
  const used = new Set((tenants || []).map(t => (t.barcodePrefix || '').toUpperCase()));
  if (!used.has(p)) return p;
  let i = 2;
  while (used.has(p + i)) i++;
  return p + i;
}

// R05 — 本商户条码前缀（租户维度）。非租户账号返回空串 → 表单不显示前缀区。
function ownBarcodePrefix(db, account) {
  if (!account || !account.tenantId) return '';
  const tn = (db.tenants || []).find(x => x.id === account.tenantId);
  return (tn && tn.barcodePrefix) || '';
}
// R05 — 拼完整条码 = 前缀 + '-' + 主体码。主体码为空 → 整个条码为空
// （AC-05-07：条码非强制，空条码保持空，绝不回落成型号）。
function composeBarcode(prefix, body) {
  const b = String(body == null ? '' : body).trim();
  if (!b) return '';
  const p = String(prefix == null ? '' : prefix).trim().toUpperCase();
  return p ? p + '-' + b : b;
}
// R05 — 全库条码查重。唯一性范围是全平台 db.products（跨租户，AC-05-04/05），
// 空条码不参与校验（AC-05-07）。exceptProductId 用于编辑时排除自身。
function findBarcodeConflict(db, barcode, exceptProductId) {
  const code = String(barcode || '').trim();
  if (!code) return null;
  const up = code.toUpperCase();
  return (db.products || []).find(p => p.id !== exceptProductId
    && String(p.barcode || '').trim().toUpperCase() === up) || null;
}

// ---- R20/R21 price helpers ----------------------------------------------
// The single read entry for purchase price. Prefers purchasePrice (newest
// stock-in price), falls back to cost (value at record creation), then price.
// NO display site may read p.cost directly — that is what keeps the three
// price concepts (purchase / market reference / channel sales) separated.
function purchasePriceOf(p) {
  if (!p) return 0;
  if (p.purchasePrice != null) return p.purchasePrice;
  if (p.cost != null) return p.cost;
  return p.price || 0;
}
function purchaseCurrencyOf(p) {
  return p.purchaseCurrency || p.currency || 'USD';
}
// R21 — patch that prepends a PurchaseRecord and refreshes the derived snapshot.
// The caller folds this into its own SINGLE setDb call (a second setDb inside
// the same event handler would overwrite the first under React batching).
function purchasePatch(product, record) {
  const old = (product && product.purchaseHistory) || [];
  return {
    purchaseHistory: [record, ...old].slice(0, 50),
    purchasePrice: record.price,
    purchaseCurrency: record.currency || 'USD',
    purchaseUpdatedAt: record.ts,
    purchaseRefNo: record.refNo || null
  };
}
function recordPurchasePrice(db, pid, record) {
  const p = ((db || {}).products || []).find(x => x.id === pid) || {};
  return purchasePatch(p, record);
}
function latestPurchase(db, pid) {
  const p = ((db || {}).products || []).find(x => x.id === pid);
  return ((p && p.purchaseHistory) || [])[0] || null;
}


function relatedTenantIds(db, tid) {
  const set = new Set([tid]);
  let changed = true;
  while (changed) {
    changed = false;
    for (const r of db.relations) {
      if (set.has(r.upstream) && !set.has(r.downstream)) { set.add(r.downstream); changed = true; }
      if (set.has(r.downstream) && !set.has(r.upstream)) { set.add(r.upstream); changed = true; }
    }
  }
  return set;
}

// upstream chain of a tenant (suppliers / parent agents) — the only source for
// inquiries and purchases; own and downstream tenants are excluded
function upstreamTenantIds(db, tid) {
  const out = new Set();
  let frontier = [tid];
  while (frontier.length) {
    const next = [];
    for (const r of db.relations) {
      if (frontier.indexOf(r.downstream) >= 0 && !out.has(r.upstream) && r.upstream !== tid) { out.add(r.upstream); next.push(r.upstream); }
    }
    frontier = next;
  }
  return out;
}

// R02 — 子账号与分销商管理分离。团队 = 本租户的账号（不含主账号）；
// 分销商 = 关系图里的下游商户（是 tenants，不是 accounts 里的记录）。
// 两端（Web / H5）共用这两个函数，避免两份过滤逻辑漂移。
// 注意：判据是「本租户账号」与「下游租户」两个集合，不要按 account.type 过滤 ——
// db.accounts 里既没有分销商（分销商是 tenants），子账号也没有独立 type。
function deriveTeam(db, account) {
  if (!account || account.type !== 'tenant' || !account.tenantId) return [];
  return db.accounts.filter(a => a.tenantId === account.tenantId && !a.main);
}

function deriveDistributors(db, account) {
  if (!account || account.type !== 'tenant' || !account.tenantId) return [];
  return db.relations
    .filter(r => r.upstream === account.tenantId)
    .map(r => db.tenants.find(t => t.id === r.downstream))
    .filter(Boolean);
}

// inquiry boundary — a product can be inquired only if its owner is an upstream tenant
function canInquireProduct(db, account, p) {
  if (!p || account.type !== 'tenant' || !account.tenantId) return false;
  const tenant = db.tenants.find(t => t.id === account.tenantId);
  if (!tenant || tenant.type === 'Supplier') return false;
  return upstreamTenantIds(db, account.tenantId).has(p.ownerId);
}

// price / stock management boundary — own-tenant products only
function canManageProduct(db, account, p) {
  return !!(p && account.type === 'tenant' && account.tenantId && p.ownerId === account.tenantId);
}

function productOwnerName(db, p) {
  const t = db.tenants.find(x => x.id === (p || {}).ownerId);
  return t ? t.name : '—';
}

// downstream sales chain of a tenant (sub-agents / resellers), nested — feeds the
// "view stock" tree: each level shows the on-hand qty of a product at that tenant
function downstreamChain(db, tid) {
  const seen = new Set([tid]);
  const build = (id) => db.relations
    .filter(r => r.upstream === id && !seen.has(r.downstream))
    .map(r => { seen.add(r.downstream); return { id: r.downstream, children: build(r.downstream) }; });
  return build(tid);
}

function docVisible(db, account, doc) {
  if (account.type === 'platform') return true;
  // P2 — a Draft document is the drafting side's private work-in-progress:
  // counterparties (and observers) must not see it before submission (a draft
  // inquiry leaked to the supplier would expose the buyer's intent).
  // Owner = the drafting tenant, resolved via the creator's account record,
  // falling back to the doc's originating side (buyer for IQ/PO/CK/RK, seller
  // for QT/FP) when the creator can't be resolved (e.g. AI-drafted quotes).
  if (doc.status === 'Draft') {
    const creator = (db.accounts || []).find(a => a.name === doc.createdBy);
    const ownerTenant = creator ? creator.tenantId : (doc.type === 'QT' || doc.type === 'FP' ? doc.seller : doc.buyer);
    return ownerTenant === account.tenantId || doc.createdBy === account.name;
  }
  // R89 — order-type documents (PO / CK / RK) are listed only when THIS tenant
  // is the buyer or the seller; related-tenant "observer" orders no longer
  // appear in the order list
  if (doc.type === 'PO' || doc.type === 'CK' || doc.type === 'RK') {
    return doc.buyer === account.tenantId || doc.seller === account.tenantId;
  }
  const rel = relatedTenantIds(db, account.tenantId);
  if (doc.buyer && rel.has(doc.buyer)) return true;
  if (doc.seller && rel.has(doc.seller)) return true;
  if (doc.createdBy === account.name) return true;
  return false;
}

function docSide(db, account, doc) {
  if (account.type === 'platform') return 'observer';
  if (doc.seller === account.tenantId) return 'seller';
  if (doc.buyer === account.tenantId) return 'buyer';
  return 'observer';
}

// R10 — 单据金额五行的唯一计算源（§2.8 口径）：
//   行原价 = qty × unitPrice
//   行折后 = 行原价 × (1 − 该行 discountPct)，未单设则用整体 discountPct
//   subtotal = Σ 行原价；discountTotal = Σ (行原价 − 行折后)
//   taxAmount = (subtotal − discountTotal) × taxRate / 100   （折扣后计税，运费不计税）
//   total    = subtotal − discountTotal + taxAmount + freight
// docAmount 保留 number 签名（24 个调用点零改动），内部转发到本函数。
function docAmountBreakdown(doc) {
  const items = (doc && doc.items) || [];
  const pct = Number(doc && doc.discountPct) || 0;
  let subtotal = 0, discountTotal = 0;
  items.forEach(it => {
    const gross = (Number(it.qty) || 0) * (Number(it.price) || 0);
    // 单行优先：用 ?? 语义（0 是合法的「无折扣」），未单设才回落整体折扣
    const rowPct = (it.discountPct === undefined || it.discountPct === null) ? pct : (Number(it.discountPct) || 0);
    subtotal += gross;
    discountTotal += gross * rowPct / 100;
  });
  // 单据已冻结金额时直接读快照（改税率不得改历史单据，AC-10-13）
  if (doc && doc.amountsFrozen) {
    return {
      subtotal: Number(doc.subtotal) || 0,
      discountTotal: Number(doc.discountTotal) || 0,
      taxAmount: Number(doc.taxAmount) || 0,
      freight: Number(doc.freight) || 0,
      taxRate: doc.taxRate === undefined ? null : doc.taxRate,
      total: Number(doc.totalAmount) || 0,
    };
  }
  // 税率以单据自身为准：未写 taxRate 的单据不计税、不显示税额行（AC-10-10）
  const rate = doc && doc.taxRate !== null && doc.taxRate !== undefined ? Number(doc.taxRate) : null;
  // 已写 taxAmount 的单据（如 FP）优先读快照，避免与开票时点税率不一致
  const taxAmount = (doc && doc.taxAmount !== undefined && doc.taxAmount !== null)
    ? Number(doc.taxAmount)
    : (rate ? Math.round((subtotal - discountTotal) * rate) / 100 : 0);
  const freight = Number(doc && doc.freight) || 0;
  return {
    subtotal: Math.round(subtotal * 100) / 100,
    discountTotal: Math.round(discountTotal * 100) / 100,
    taxAmount, freight,
    taxRate: rate,
    total: Math.round((subtotal - discountTotal + taxAmount + freight) * 100) / 100,
  };
}
function docAmount(doc) { return docAmountBreakdown(doc).total; }

// R15 — demo-grade voucher parse (Q35 演示态): the structured result is derived
// from the file NAME only, e.g. "payment-1200-TRF88213-2026-11-03-cash.jpg"
// → { method, ref, amount, date }. parseConfidence stays 'demo'.
function parseVoucherDemo(fileName) {
  const name = String(fileName || '');
  const dm = name.match(/(\d{4}-\d{2}-\d{2})/);
  const am = name.match(/(?:^|[^0-9.])(\d+(?:\.\d{1,2})?)(?:[^0-9.]|$)/);
  const rm = name.replace(/\.[A-Za-z0-9]+$/, '').match(/[A-Za-z]{2,}[A-Za-z0-9]*\d[A-Za-z0-9-]*/);
  const method = /cash/i.test(name) ? 'Cash' : /pos\b/i.test(name) ? 'POS' : /cheq/i.test(name) ? 'Cheque' : 'Bank Transfer';
  return { method, ref: rm ? rm[0] : '', amount: am ? am[1] : '', date: dm ? dm[1] : '' };
}
// R10 — 单行金额三列（原始价 / 折后价 / 优惠金额）。行折扣优先于整体折扣。
function lineAmounts(items, cartPct) {
  const pct = Number(cartPct) || 0;
  return (items || []).map(it => {
    const gross = (Number(it.qty) || 0) * (Number(it.price) || 0);
    const rowPct = (it.discountPct === undefined || it.discountPct === null) ? pct : (Number(it.discountPct) || 0);
    const net = gross * (1 - rowPct / 100);
    return { gross: Math.round(gross * 100) / 100, pct: rowPct, net: Math.round(net * 100) / 100, saving: Math.round((gross - net) * 100) / 100 };
  });
}
// R10 — 批量调价纯函数（Web / H5 共用同一份，避免两端行为漂移）
//   op = { type:'pct', value:20, target:'sale'|'market'|'both' }
//      | { type:'set', value:99, target:... }
//      | { type:'markup', value:1.3 }        // 采购价 × 倍率 → 写渠道销售价
//   value 为负数即下调（AC-10-02）；预览只算不写（AC-10-05）。
function applyBulk(rows, op) {
  return (rows || []).map(r => {
    const next = { ...r };
    const apply = (key, base) => {
      if (op.type === 'pct') next[key] = +(base * (1 + op.value / 100)).toFixed(2);
      if (op.type === 'set') next[key] = +Number(op.value).toFixed(2);
    };
    if (op.type === 'markup') {
      next.salePrice = +(Number(r.purchasePrice || 0) * op.value).toFixed(2);
      return next;
    }
    if (op.target === 'sale' || op.target === 'both') apply('salePrice', r.salePrice);
    if (op.target === 'market' || op.target === 'both') apply('marketPrice', r.marketPrice);
    return next;
  });
}

function nextNo(prefix, docs) {
  const d = new Date();
  const ds = `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;
  // R93 — use max existing sequence (not count+1) so sparse/seeded numbers never collide
  const re = new RegExp(`^${prefix}-${ds}-(\\d+)$`);
  let max = 0;
  docs.forEach(x => { const m = x.no && x.no.match(re); if (m) max = Math.max(max, parseInt(m[1], 10)); });
  return `${prefix}-${ds}-${String(max + 1).padStart(3,'0')}`;
}

const STATUS_META = {
  IQ: { Draft: ['Draft', 'info'], Submitted: ['Submitted', 'primary'], Quoted: ['Quoted', 'purple'], Closed: ['Closed', 'dark'] },
  QT: { Draft: ['Draft', 'info'], Sent: ['Sent', 'primary'], Accepted: ['Accepted', 'success'], Rejected: ['Rejected', 'danger'], Expired: ['Expired', 'dark'] },
  // R82 — order state machine: 待接收 → 待付款 → 待出库 → 待出货 → 待收货 → 已收货 / 部分收货 / 已拒收
  // R86 — order (PO) statuses are EXACTLY the nine order-flow statuses
  // R88 — raw keys unchanged (logic); display names come from PO_ORDER_LABEL.
  // New raw status 'Rejected' = 已拒绝 (supplier rejected the order), distinct
  // from 'Receipt Rejected' = 已拒收 (buyer rejected the shipment).
  PO: { 'Pending Acceptance': ['Pending Acceptance', 'warning'], 'Pending Payment': ['Accepted', 'warning'], 'Pending Payment Confirmation': ['Payment Review', 'warning'], 'Pending Outbound': ['Paid', 'warning'], 'Pending Picking': ['Pending Picking', 'warning'], 'Picking': ['Picking', 'warning'], 'Pending Shipment': ['Shipped', 'primary'], 'Pending Receipt': ['Shipped', 'primary'], Received: ['Received', 'success'], 'Partially Received': ['Partially Received', 'warning'], 'Receipt Rejected': ['Receipt Rejected', 'danger'], Rejected: ['Rejected', 'danger'], 'Receiving Closed': ['Receiving Closed', 'dark'] },
  CK: { 'Picking': ['Picking', 'warning'], 'Pending Shipment': ['Pending Shipment', 'warning'], Shipped: ['Shipped', 'primary'], Received: ['Received', 'success'], 'Partial Variance': ['Partial Variance', 'warning'], Rejected: ['Rejected', 'danger'] },
  RK: { Received: ['Received', 'success'], 'Partial Variance': ['Partial Variance', 'warning'], Rejected: ['Rejected', 'danger'] },
  FP: { Draft: ['Draft', 'info'], Issued: ['Issued', 'success'], Archived: ['Archived', 'dark'], RedFlushed: ['Red-flushed', 'danger'] },
};
// R85 — the order (PO) status machine has exactly these nine statuses:
// 待接收 → 待付款 → 待出库 → 待发货 → 待收货 → 已收货 / 部分收货 / 已拒收 / 终止收货
// R88 — order statuses per the confirmed state table. The user-facing names
// are: 待接收 → 已接受(原待付款) → 已付款(原待发货前段) → 已发货(原待收货)
// → 已收货 / 部分收货 / 已拒收 / 已拒绝 / 已终止收货. ORDER_FLOW_STATUSES now
// carries the nine DISPLAY names (used by the filter panels); the raw
// statuses keep driving all logic, actions and transitions.
const ORDER_FLOW_STATUSES = ['Pending Acceptance', 'Accepted', 'Payment Review', 'Paid', 'Pending Picking', 'Picking', 'Shipped', 'Received', 'Partially Received', 'Receiving Closed', 'Rejected', 'Receipt Rejected'];
// R85 — 待收货 (shipped, awaiting receipt) or later: outbound order / waybill
// print & export unlock at this stage in the PO detail (raw statuses)
// R99h — raw 'Pending Shipment' ALSO displays 已发货 (ship form submitted →
// CK + waybill already generated; dispatch is only an internal logistics
// confirmation), so it must unlock the outbound/waybill entries too — without
// it, an order the user ships THEMSELVES showed no 查看发货单/打印路单/导出
// on its own detail page.
const PO_SHIPPED_OR_LATER = ['Pending Shipment', 'Pending Receipt', 'Received', 'Partially Received', 'Receipt Rejected', 'Receiving Closed'];
// R99j — 查看发票 unlock statuses, per the user's explicit list (不区分买卖角色):
// 已接受 / 已付款 / 已发货 / 已收货 / 部分收货 / 已终止收货 / 已拒收 — i.e. every
// order-flow status EXCEPT 待接受 (Pending Acceptance) and 已拒绝 (Rejected).
// Both roles (buyer & seller) see the entry; the doc-visibility layer already
// guarantees each party can open the PO detail.
const PO_ACCEPTED_OR_LATER = ['Pending Payment', 'Pending Payment Confirmation', 'Pending Outbound', 'Pending Picking', 'Picking', 'Pending Shipment', 'Pending Receipt', 'Received', 'Partially Received', 'Receiving Closed', 'Receipt Rejected'];
// R88 — PO raw status → order-flow display name. Pending Payment displays
// 已接受 (accepted + invoice issued), Pending Outbound displays 已付款
// (payment recorded, awaiting shipment), Pending Shipment AND Pending
// Receipt both display 已发货 (ship form submitted → CK + waybill generated;
// dispatch is an internal logistics confirmation). Supplier rejection gets
// its own raw status 'Rejected' (已拒绝), distinct from the buyer's
// shipment rejection 'Receipt Rejected' (已拒收).
const PO_ORDER_LABEL = {
  'Pending Acceptance': 'Pending Acceptance',
  'Pending Payment': 'Accepted',
  'Pending Payment Confirmation': 'Payment Review',
  'Pending Outbound': 'Paid',
  'Pending Picking': 'Pending Picking',
  'Picking': 'Picking',
  'Pending Shipment': 'Shipped',
  'Pending Receipt': 'Shipped',
  'Received': 'Received',
  'Partially Received': 'Partially Received',
  'Receipt Rejected': 'Receipt Rejected',
  'Rejected': 'Rejected',
  'Receiving Closed': 'Receiving Closed',
};
// R87/R88 — in the order list / order detail, CK (outbound) and RK (inbound)
// documents display the corresponding ORDER-flow status names instead of
// their raw logistics statuses (display-level only).
const CK_RK_ORDER_LABEL = {
  'Picking': 'Picking',
  'Pending Shipment': 'Shipped',
  'Shipped': 'Shipped',
  'Received': 'Received',
  'Partial Variance': 'Partially Received',
  'Rejected': 'Receipt Rejected',
};
// tag colour per order-flow DISPLAY name
const ORDER_DISPLAY_CLASS = {
  'Pending Acceptance': 'warning',
  'Accepted': 'warning',
  'Paid': 'primary',
  'Pending Picking': 'warning',
  'Picking': 'warning',
  'Shipped': 'primary',
  'Received': 'success',
  'Partially Received': 'warning',
  'Receiving Closed': 'dark',
  'Rejected': 'danger',
  'Receipt Rejected': 'danger',
};
// R99p — mobile Trade list sort rule: 先按处理状态（待处理在前，已处理在后），
// 组内再按单据时间由近到远. 待处理 = the doc offers ACTION verbs to the
// CURRENT viewer (有操作功能的列表项); 已处理 = no action verbs available
// (无操作功能的列表项). View / Print / Edit are navigation/viewing entries,
// not flow actions, so they do NOT count as 待处理.
const VIEW_ONLY_VERBS = ['View', 'Print', 'Edit'];
function docPending(db, account, doc) {
  return docActions(db, account, doc).some(v => !VIEW_ONLY_VERBS.includes(v));
}
// R99p — list comparator: 待处理 (has action verbs) first, 已处理 (no verbs)
// after; within each group newest first (由近到远) by document time.
function docListCompare(db, account, a, b) {
  const ha = docPending(db, account, a) ? 0 : 1;
  const hb = docPending(db, account, b) ? 0 : 1;
  if (ha !== hb) return ha - hb;
  const ta = a.createdAt || '';
  const tb = b.createdAt || '';
  return ta < tb ? 1 : ta > tb ? -1 : 0;
}
// P1 — a Sent quote past its Valid Until reads as Expired everywhere
// (status tag, status chips, list filters)
function quoteExpired(doc) {
  if (!doc || !doc.validUntil) return false;
  const n = new Date();
  const today = n.getFullYear() + '-' + String(n.getMonth() + 1).padStart(2, '0') + '-' + String(n.getDate()).padStart(2, '0');
  return doc.validUntil < today;
}
function docStatusOf(doc) {
  if (doc && doc.type === 'QT' && doc.status === 'Sent' && quoteExpired(doc)) return 'Expired';
  return doc && doc.status;
}
function orderDisplayStatus(doc) {
  if (doc.type === 'QT' && doc.status === 'Sent' && quoteExpired(doc)) return 'Expired';
  if (doc.type === 'PO' && PO_ORDER_LABEL[doc.status]) return PO_ORDER_LABEL[doc.status];
  if ((doc.type === 'CK' || doc.type === 'RK') && CK_RK_ORDER_LABEL[doc.status]) return CK_RK_ORDER_LABEL[doc.status];
  return doc.status;
}
function statusLabel(type, status) {
  if (type === 'PO' && PO_ORDER_LABEL[status]) return PO_ORDER_LABEL[status];
  if ((type === 'CK' || type === 'RK') && CK_RK_ORDER_LABEL[status]) return CK_RK_ORDER_LABEL[status];
  const m = (STATUS_META[type] || {})[status]; return m ? m[0] : status;
}
function statusTagClass(type, status) {
  if (type === 'PO' && PO_ORDER_LABEL[status]) return ORDER_DISPLAY_CLASS[PO_ORDER_LABEL[status]] || 'info';
  if ((type === 'CK' || type === 'RK') && CK_RK_ORDER_LABEL[status]) return ORDER_DISPLAY_CLASS[CK_RK_ORDER_LABEL[status]] || 'info';
  const m = (STATUS_META[type] || {})[status]; return m ? m[1] : 'info';
}
// R88 — status filter options per document tab. PO offers the nine order-flow
// DISPLAY names; CK/RK offer their unique display names (raw statuses that
// share a display name collapse into one option); other tabs keep raw values.
function tabStatusOptions(tab) {
  if (tab === 'PO') return ORDER_FLOW_STATUSES.map(s => ({ value: s, label: s }));
  if (tab === 'CK' || tab === 'RK') {
    const seen = []; const out = [];
    Object.keys(STATUS_META[tab] || {}).forEach(r => {
      const disp = statusLabel(tab, r);
      if (!seen.includes(disp)) { seen.push(disp); out.push({ value: disp, label: disp }); }
    });
    out.sort((a, b) => {
      const ia = ORDER_FLOW_STATUSES.indexOf(a.value), ib = ORDER_FLOW_STATUSES.indexOf(b.value);
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
    });
    return out;
  }
  return Object.keys(STATUS_META[tab] || {}).map(s => ({ value: s, label: statusLabel(tab, s) }));
}

// R92 — CK/RK list items now expose the order-flow buyer actions (确认收货 /
// 重新收货 / 补货 / 终止收货). Those actions always operate on the parent
// PURCHASE ORDER: PO → itself; CK → the PO it was generated from; RK → the PO
// behind its CK. Returns null when the parent cannot be resolved.
function parentPoOf(db, doc) {
  if (doc.type === 'PO') return doc;
  if (doc.type === 'CK') return db.docs.find(d => d.type === 'PO' && d.no === doc.poNo) || null;
  if (doc.type === 'RK') {
    const ck = db.docs.find(d => d.type === 'CK' && d.no === doc.ckNo);
    return ck ? (db.docs.find(d => d.type === 'PO' && d.no === ck.poNo) || null) : null;
  }
  return null;
}

function docActions(db, account, doc) {
  if (account.type === 'platform') return [];
  const side = docSide(db, account, doc);
  const a = [];
  if (doc.type === 'IQ') {
    if (side === 'buyer') {
      if (doc.status === 'Draft') a.push('Edit', 'Submit', 'Delete');
      if (doc.status === 'Submitted') a.push('Close');
    }
    if (side === 'seller' && doc.status === 'Submitted') a.push('Quote');
  }
  if (doc.type === 'QT') {
    if (side === 'seller') {
      // AI generates a Draft quote — the supplier confirms it with one tap
      // (flow: AI draft → Confirm Quote → link pushed to the buyer)
      if (doc.status === 'Draft') a.push('Edit', 'Confirm Quote');
      if (doc.status === 'Sent') a.push('Edit');
    }
    if (side === 'buyer' && doc.status === 'Sent') {
      // P1 — an expired Sent quote is no longer acceptable; the buyer may
      // still reject it to close the flow
      a.push(...(quoteExpired(doc) ? [] : ['Accept']), 'Reject');
    }
  }
  if (doc.type === 'PO') {
    if (side === 'buyer') {
      // R86 — no Draft stage for orders: a PO is born at 待接收 the moment the
      // buyer accepts the quote, so the buyer has no draft actions on a PO
      // R83 — buyer can re-receive the outstanding or close the order after
      // a partial receipt (终态: 已收货 / 已终止收货)
      // R91 — per the status/action table: at 已发货 the buyer confirms
      // receipt directly on the order, and at 部分收货 the buyer can also
      // request the replenishment shipment (补货[买方])
      // R92 — 已发货 covers BOTH raw pre-receipt stages (Pending Shipment =
      // CK + waybill generated; Pending Receipt = dispatched): the table says
      // the buyer can confirm receipt as soon as the outbound + waybill exist
      if (['Pending Shipment', 'Pending Receipt'].includes(doc.status)) a.push('Confirm Receipt');
      if (doc.status === 'Partially Received') a.push('Re-receive', 'Replenish', 'Terminate Receiving');
    }
    if (side === 'seller') {
      // R81/R82 — supplier accepts or rejects the placed order (rejection
      // requires a reason); acceptance auto-issues the invoice → 待付款
      if (doc.status === 'Pending Acceptance') a.push('Accept', 'Reject');
      // buyer pays OFFLINE; the supplier records the payment here (→ 待出库)
      if (!doc.paid && ['Pending Payment', 'Pending Outbound', 'Pending Shipment', 'Pending Receipt'].includes(doc.status)) a.push('Record Payment');
      // R15 — supplier confirms the recorded payment (已付款待确认 → 待出库)
      if (doc.status === 'Pending Payment Confirmation') a.push('Confirm Payment');
      // 确认发货 (待出库 + paid) → generates CK + waybill (R91: 补货 now buyer-side)
      // R15 — status is the SOLE gate: Pending Outbound is reachable only after payment confirmation
      if (doc.status === 'Pending Outbound') a.push('Ship');
      // R83 — supplier issues a replenishment outbound to cover the shortfall
      // after a partial receipt (buyer may Re-receive or Terminate Receiving)
      // R91 — 补货 moved to the BUYER side per the status/action table
      // fallback (invoice is normally auto-issued on acceptance)
      if (['Received', 'Partially Received'].includes(doc.status) && !db.docs.some(d => d.type === 'FP' && d.poNo === doc.no)) a.push('Create Invoice');
    }
  }
  if (doc.type === 'CK') {
    // R16 — CK is born at 拣货中: the seller picks first (Start Picking opens
    // the picking page); Dispatch exists ONLY after picking completes
    // (AC-16-01/05). fromStaging CKs (no PO behind them) have no dispatch flow.
    if (side === 'seller' && doc.status === 'Picking') a.push('Start Picking');
    // R82 — seller dispatches the generated outbound order (待出货 → 待收货)
    if (side === 'seller' && doc.status === 'Pending Shipment' && !doc.fromStaging) a.push('Dispatch');
    // R92 — order-flow table applied to ALL order list items: 已发货 (raw
    // Pending Shipment / Shipped) → buyer Confirm Receipt; 部分收货
    // (Partial Variance) → buyer recovery actions, resolved to the parent order
    if (side === 'buyer' && ['Pending Shipment', 'Shipped'].includes(doc.status)) a.push('Confirm Receipt');
    // R94 — recovery verbs on a CK are only valid while the PARENT order is
    // still 部分收货 (once re-received fully / replenished / terminated the chips disappear)
    if (side === 'buyer' && doc.status === 'Partial Variance') {
      const poOf = db.docs.find(d => d.type === 'PO' && d.no === doc.poNo);
      if (poOf && poOf.status === 'Partially Received') a.push('Re-receive', 'Replenish', 'Terminate Receiving');
    }
    if (side === 'buyer' || side === 'seller') a.push('Print');
  }
  if (doc.type === 'RK') {
    // R92 — 部分收货 (Partial Variance) inbound record → buyer recovery
    // actions on the parent order (重新收货/补货/终止收货[买方])
    // R94 — gated on the parent PO still being 部分收货 (same as CK above)
    if (side === 'buyer' && doc.status === 'Partial Variance') {
      const ckOf = db.docs.find(d => d.type === 'CK' && d.no === doc.ckNo);
      const poOf = ckOf && db.docs.find(d => d.type === 'PO' && d.no === ckOf.poNo);
      if (poOf && poOf.status === 'Partially Received') a.push('Re-receive', 'Replenish', 'Terminate Receiving');
    }
    // supplier can issue the invoice right from the inbound record after receiving
    if (side === 'seller' && ['Received', 'Partial Variance'].includes(doc.status)) {
      const ck = db.docs.find(d => d.type === 'CK' && d.no === doc.ckNo);
      if (ck && !db.docs.some(d => d.type === 'FP' && d.poNo === ck.poNo)) a.push('Create Invoice');
    }
  }
  if (doc.type === 'FP' && doc.status !== 'Draft') {
    // buyer confirms the pushed invoice link → archived (flow end)
    if (side === 'buyer' && doc.status === 'Issued') a.push('Confirm Invoice');
    a.push('Download');
  }
  a.push('View', 'Print');
  // ensure unique and order stable
  const order = ['View', 'Edit', 'Confirm Quote', 'Submit', 'Place Order', 'Delete', 'Quote', 'Accept', 'Reject', 'Approve', 'Record Payment', 'Confirm Payment', 'Ship', 'Dispatch', 'Confirm Receipt', 'Create Invoice', 'Confirm Invoice', 'Re-receive', 'Replenish', 'Terminate Receiving', 'Print', 'Download', 'Cancel', 'Close'];
  const uniq = [];
  for (const k of order) { if (a.includes(k) && !uniq.includes(k)) uniq.push(k); }
  return uniq;
}

// ---- null-coalescing helper -----------------------------------------
// In-browser Babel only strips JSX — ?. and ?? pass through untranspiled and
// are a hard SyntaxError on older embedded webviews (Feishu in-app browser,
// old Android). Use ifnull(v, d) / (x || {}) instead. See also index.html
// boot guard.
function ifnull(v, d) { return v == null ? d : v; }

// R79 — market reference price carries its OWN currency code (independent of
// the channel sales price currency); falls back to the product currency when
// never set, so existing data renders unchanged
function marketCurOf(p) { return (p && p.marketCurrency) || (p && p.currency) || 'USD'; }

// ---- file download helpers (demo-grade, front-end only) ----
function csvEscape(v) {
  const s = String(ifnull(v, ''));
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function downloadFile(filename, content, mime) {
  // UTF-8 BOM so Excel opens CJK content correctly
  const blob = new Blob(['\uFEFF' + content], { type: mime || 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

function downloadProductTemplate() {
  const header = 'Product Name,Spec,Model,Brand,Unit,Price,Currency,Stock,Categories';
  const rows = [
    'Solar Inverter 3kW,3kW / MPPT / 48V,SK-INV-3K,SunKing,pcs,199.00,USD,60,Solar Inverters; Accessories',
    'LiFePO4 Battery 50Ah,50Ah / 12.8V / BMS,VC-LFP-50,VoltCore,pcs,105.00,USD,120,Batteries',
    '(required),(optional),(unique),(optional),pcs / box / set / kg,> 0,USD / NGN / CNY,>= 0,semicolon-separated category names)',
  ];
  downloadFile('product_import_template.csv', [header, ...rows].join('\n'));
}

function downloadInvoiceFile(db, doc) {
  const lines = [
    ['Invoice No', doc.no], ['Seller', tenantName(db, doc.seller)], ['Buyer', tenantName(db, doc.buyer)], ['Order Ref', doc.poNo || ''],
    ['Issue Date', doc.issueDate || ''], ['Currency', doc.currency], ['Status', doc.status], [],
    ['Product', 'Spec', 'Qty', 'Channel sale price', 'Amount'],
    ...doc.items.map(it => [it.name, it.spec, it.qty, it.price, it.qty * it.price]),
    [], ['Total', '', '', '', docAmount(doc)],
  ];
  downloadFile(`${doc.no}_invoice.csv`, lines.map(r => r.map(csvEscape).join(',')).join('\n'));
}

// R83 — outbound order / waybill export (mirrors downloadInvoiceFile shape)
function downloadOutboundFile(db, doc) {
  const ckItems = doc.items || [];
  const waybill = doc.waybill || {};
  const lines = [
    ['Outbound No', doc.no], ['Order Ref', doc.poNo || ''], ['Seller', tenantName(db, doc.seller)], ['Buyer', tenantName(db, doc.buyer)],
    ['Dispatch Date', doc.dispatchDate || ''], ['Status', doc.status], [],
    ['Waybill No', waybill.no || ''], ['Carrier', waybill.carrier || ''], ['Plate', waybill.plate || ''], ['Driver', waybill.driver || ''], ['Driver Phone', waybill.phone || ''],
    [],
    ['Product', 'Spec', 'Qty'],
    ...ckItems.map(it => [it.name, it.spec, it.qty]),
  ];
  downloadFile(`${doc.no}_outbound.csv`, lines.map(r => r.map(csvEscape).join(',')).join('\n'));
}

// R14 — 返回库存提示文案（无提示时返回 ''，AC-14-02：充足时完全不提）。
// 规则：任一商品 <= 0 → 断货话术（更强，AC-14-07）；任一商品 <= threshold → 少许话术；
//      多商品时指名低库存品（最多列 2 个，避免话术过长，AC-14-06）。
// 纯文本话术层，绝不改变 price / discount（AC-14-08）。
function stockHintFor(db, tenantId, pids, threshold) {
  const stock = db.stock[tenantId] || {};
  const th = Number(threshold != null ? threshold : 30);
  const lows = [], outs = [];
  (pids || []).forEach(pid => {
    const p = db.products.find(x => x.id === pid);
    if (!p) return;
    const q = stock[pid] || 0;
    if (q <= 0) outs.push(p.name);
    else if (q <= th) lows.push({ name: p.name, qty: q });
  });
  if (outs.length) return t('Out of stock — pre-order available') + ' · ' + outs.slice(0, 2).join(', ');
  if (lows.length) return t('Low stock — order soon') + ' · ' + lows.slice(0, 2).map(x => x.name).join(', ');
  return '';
}

// R13 — AI 让价阶梯（design 2.7）。round 从 0 起。两处硬编码（会话议价 / AI 草稿）都必须调
// 这一个函数，不允许各写一份。人工折扣路径（cart.jsx / DocDetailDialog）不校 aiPolicy（AC-13-08）。
function nextAiDiscount(policy, round) {
  const p = policy || {};
  const floor = Number(p.floorDiscount != null ? p.floorDiscount : 0.97);
  const step = Number(p.stepSize || 0.01);
  const maxRounds = Number(p.maxRounds || 3);
  // 从「无折扣」起，每轮降一个 step，但不得低于 floor
  const raw = 1 - step * (round + 1);
  const discount = Math.max(raw, floor);
  const hitFloor = discount <= floor + 1e-9;
  return { discount: +discount.toFixed(4), hitFloor, canContinue: !hitFloor && round + 1 < maxRounds };
}

